$assert(strpos($metrics,'ensureGeographicIntegrityForRoute')!==false && strpos($metrics,'reconcileProjectGeographicIntegrity')!==false,'route reconciliation');
$assert(strpos($metrics,"\$refreshVersion = 'google_routes_geography_v3'")!==false,'routing refresh generation');
$assert(strpos($campaigns,'routing_country_code')!==false && strpos($campaigns,'componentRestrictions')!==false,'campaign routing country');
$assert(strpos($routes,'routing_country_code')!==false && strpos($routes,'routingCountryForSelection')!==false,'route ui country');
$assert(strpos($assign,'reconcile_routing_geography')!==false && strpos($assign,'Revalidar país, endpoints, PDVs e km')!==false,'historical repair');
$assert(strpos($mail,'ensureGeographicIntegrityForRoute')!==false && strpos($mail,'$subjectAnchorDate')!==false,'mail source of truth');
